import { SLOT_MINUTES } from './config.js';

export function dailySlots(open: string, close: string): string[] {
  const out: string[] = [];
  let [h, m] = open.split(':').map(Number);
  const [ch, cm] = close.split(':').map(Number);
  while (h * 60 + m + SLOT_MINUTES <= ch * 60 + cm) {
    out.push(`${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`);
    m += SLOT_MINUTES; h += Math.floor(m / 60); m %= 60;
  }
  return out;
}

