const PATTERN = /^[A-Z]{6}\d{2}[A-Z]\d{2}[A-Z]\d{3}[A-Z]$/;

export function isValidFiscalCode(code: string): boolean {
  const c = code.toUpperCase();
  if (!PATTERN.test(c)) return false;
  return checkChar(c.slice(0, 15)) === c[15];
}

declare function checkChar(body: string): string;

