const DAY_MS = 24 * 60 * 60 * 1000;

// Clinic policy: full session fee if cancelled less than 24h before.
export function cancellationFee(startsAt: Date, now: Date, sessionFee: number): number {
  return startsAt.getTime() - now.getTime() < DAY_MS ? sessionFee : 0;
}

