const BASE = 'https://api.skebby.it/API/v1.0/REST';

export async function sendSms(to: string, body: string, sender = 'FisioSud') {
  const res = await fetch(`${BASE}/sms`, {
    method: 'POST',
    headers: { user_key: process.env.SKEBBY_USER!, Session_key: process.env.SKEBBY_SESSION!, 'Content-Type': 'application/json' },
    body: JSON.stringify({ message_type: 'GP', message: body, recipient: [to], sender }),
  });
  if (!res.ok) throw new Error(`skebby ${res.status}`);
}

