export interface Session { insurerId: string; sessionType: string; date: string; status: string }

export function groupByInsurerMonth(sessions: Session[]): Map<string, Session[]> {
  const out = new Map<string, Session[]>();
  for (const s of sessions) {
    const key = `${s.insurerId}:${s.date.slice(0, 7)}`;
    out.set(key, [...(out.get(key) ?? []), s]);
  }
  return out;
}

