import { insurers } from '../insurers/catalogue.js';
import type { Session } from './group.js';

export function totalCents(insurerId: string, sessions: Session[]): number {
  const tariffs = insurers.find((i) => i.id === insurerId)?.tariffs ?? [];
  return sessions.reduce((sum, s) => sum + (tariffs.find((t) => t.sessionType === s.sessionType)?.cents ?? 0), 0);
}

