const counters = new Map<string, number>();

// Progressive number per issuing clinic and year.
export function nextInvoiceNumber(clinicId: string, year: number): string {
  const key = `${clinicId}:${year}`;
  const n = (counters.get(key) ?? 0) + 1;
  counters.set(key, n);
  return `${n}/${year}/${clinicId.toUpperCase()}`;
}

